1	using Guardrails.Core.Graph;
2	
3	namespace Guardrails.Core.Tests;
4	
5	/// <summary>
6	/// Unit tests for <see cref="HtmlDiagramRenderer.Render"/> (issue #33): the self-contained local
7	/// <c>diagram.html</c> viewer. Pure string mapping — no disk. Pins the provenance line, the
8	/// verbatim-source embedding, the interaction prerequisites (loose security for clicks, pan/zoom,
9	/// fullscreen), determinism, and newline normalization.
10	/// </summary>
11	public sealed class HtmlDiagramRendererTests
12	{
13	    private const string Hash = "abc123def456";
14	    private const string Source = "flowchart TD\n  task_a[\"a\"]:::task\n  classDef task fill:#cfe8ff;";
15	
16	    private static readonly IReadOnlyDictionary<string, string> NoTargets =
17	        new Dictionary<string, string>(StringComparer.Ordinal);
18	
19	    private static readonly IReadOnlyDictionary<string, string> OneTarget =
20	        new Dictionary<string, string>(StringComparer.Ordinal) { ["task_01_a"] = "tasks/01-a/" };
21	
22	    [Fact]
23	    public void Render_FirstLine_IsProvenanceComment_WithSameHash()
24	    {
25	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
26	        string firstLine = html.Split('\n')[0];
27	
28	        // Same provenance shape as diagram.md, and FIRST so the \A-anchored reader (graph --check)
29	        // matches it in both files.
30	        Assert.Equal($"<!-- guardrails:graph v1 source-sha256={Hash} -->", firstLine);
31	    }
32	
33	    [Fact]
34	    public void Render_EmbedsSourceVerbatim_InRawTextScript()
35	    {
36	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
37	
38	        Assert.Contains("type=\"text/plain\"", html);
39	        Assert.Contains(Source, html); // verbatim — not interpolated into a JS string
40	        Assert.Contains("<!doctype html>", html);
41	    }
42	
43	    [Fact]
44	    public void Render_EnablesClicksAndNavigation()
45	    {
46	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
47	
48	        // Clicks (node -> source file) only fire when mermaid runs in 'loose' security.
49	        Assert.Contains("securityLevel: 'loose'", html);
50	        // Pan/zoom + fullscreen affordances.
51	        Assert.Contains("svg-pan-zoom", html);
52	        Assert.Contains("requestFullscreen", html);
53	    }
54	
55	    [Fact]
56	    public void Render_RaisesMermaidSizeCeilings_SoLargeDagsRender()
57	    {
58	        // Issue #108: a large plan's DAG source exceeds Mermaid's default 50 000-char maxTextSize
59	        // and/or 500-edge maxEdges ceiling, so mermaid.render throws and the page falls back to
60	        // "could not render". The fix lifts BOTH ceilings in mermaid.initialize — assert they are
61	        // present (a regression that drops either re-introduces the big-plan render failure).
62	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
63	
64	        Assert.Contains("maxTextSize: 5000000", html);
65	        Assert.Contains("maxEdges: 100000", html);
66	    }
67	
68	    [Fact]
69	    public void Render_IsDeterministic()
70	    {
71	        Assert.Equal(
72	            HtmlDiagramRenderer.Render(Source, Hash, OneTarget),
73	            HtmlDiagramRenderer.Render(Source, Hash, OneTarget));
74	    }
75	
76	    [Fact]
77	    public void Render_NormalizesCrlf_NoCarriageReturnsInOutput()
78	    {
79	        string html = HtmlDiagramRenderer.Render("flowchart TD\r\n  a-->b\r\n", Hash, NoTargets);
80	        Assert.DoesNotContain('\r', html);
81	    }
82	
83	    [Fact]
84	    public void Render_EmptyHash_Throws()
85	    {
86	        Assert.Throws<ArgumentException>(() => HtmlDiagramRenderer.Render(Source, "", NoTargets));
87	    }
88	
89	    [Fact]
90	    public void Render_NullTaskFolderTargets_Throws()
91	    {
92	        Assert.Throws<ArgumentNullException>(() => HtmlDiagramRenderer.Render(Source, Hash, null!));
93	    }
94	
95	    // === legend overlay (outside the Mermaid graph; see MermaidRenderer remarks) =======
96	
97	    [Fact]
98	    public void Render_IncludesALegendOverlayDiv_OutsideTheEmbeddedMermaidSource()
99	    {
100	        // A Mermaid-native legend was prototyped and rendered broken headless (dagre treats a
101	        // disconnected subgraph as a phantom extra "task"); the only working placement is an HTML
102	        // overlay div outside the embedded Mermaid <script> source, mirroring #bar/#hint.
103	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
104	
105	        Assert.Contains("id=\"legend\"", html, StringComparison.Ordinal);
106	    }
107	
108	    [Fact]
109	    public void Render_LegendOverlay_StatesBothAColorAndABeforeAfterTimingWord()
110	    {
111	        // A bare category name would not preserve the "preflights run before, guardrails run
112	        // after" semantic the removed nested boxes used to convey visually — the legend must spell
113	        // out both the colour mapping AND the timing/consequence in words.
114	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
115	
116	        Assert.Contains("Preflight", html, StringComparison.Ordinal);
117	        Assert.Contains("Guardrail", html, StringComparison.Ordinal);
118	        Assert.Contains("BEFORE", html, StringComparison.Ordinal);
119	        Assert.Contains("AFTER", html, StringComparison.Ordinal);
120	    }
121	
122	    [Fact]
123	    public void Render_LegendOverlay_IsNotInsideTheEmbeddedGraphSourceScript()
124	    {
125	        // The legend must live OUTSIDE the raw-text <script id="graph-source"> element — it is
126	        // not part of the Mermaid source, so it can never affect anything that parses that source
127	        // (rendering) or hashes it (GraphSourceHash, via MermaidRenderer.SemanticContent).
128	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
129	
130	        int scriptStart = html.IndexOf("id=\"graph-source\"", StringComparison.Ordinal);
131	        int scriptEnd = html.IndexOf("</script>", scriptStart, StringComparison.Ordinal);
132	        string scriptContent = html[scriptStart..scriptEnd];
133	
134	        Assert.DoesNotContain("legend", scriptContent, StringComparison.Ordinal);
135	    }
136	
137	    // === task-container title-band overlay (issue #232/#233 superseded, issue #235) ====
138	    //
139	    // The Mermaid-source anchor-node mechanism (#211) proved useless in practice — a real
140	    // headless-Chrome measurement found the anchor covering only 0.44% of a content-dense
141	    // container's area, off-center, missed by every realistic click point. The fix instead
142	    // injects a post-render SVG overlay on the container's title/label band via JavaScript.
143	
144	    [Fact]
145	    public void Render_EmbedsTaskFolderTargets_AsJsonSideTable()
146	    {
147	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
148	
149	        Assert.Contains("id=\"task-folder-targets\"", html, StringComparison.Ordinal);
150	        Assert.Contains("\"task_01_a\"", html, StringComparison.Ordinal);
151	        Assert.Contains("tasks/01-a/", html, StringComparison.Ordinal);
152	    }
153	
154	    [Fact]
155	    public void Render_NoLongerEmitsAnchorNodeMechanism()
156	    {
157	        // The #211 anchor-node click mechanism (Mermaid-source invisible node + classDef) is
158	        // superseded entirely — HtmlDiagramRenderer must not reference it either.
159	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
160	
161	        Assert.DoesNotContain("classDef invisible", html, StringComparison.Ordinal);
162	    }
163	
164	    [Fact]
165	    public void Render_OverlayScript_AppendsToCluster_NotInsertsFirst()
166	    {
167	        // Load-bearing z-order fix: appendChild (not insertBefore as firstChild) — see class
168	        // remarks and HtmlDiagramRenderer's remarks for why insertBefore silently blocks clicks
169	        // (it lands the overlay BEHIND the cluster's own background rect).
170	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
171	
172	        Assert.Contains("cluster.appendChild(a)", html, StringComparison.Ordinal);
173	        Assert.DoesNotContain("insertBefore(a, cluster.firstChild", html, StringComparison.Ordinal);
174	    }
175	
176	    [Fact]
177	    public void Render_OverlayScript_ComputesBandFromClusterAndLabelBBox()
178	    {
179	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
180	
181	        Assert.Contains("cluster.getBBox()", html, StringComparison.Ordinal);
182	        Assert.Contains("label.getBBox()", html, StringComparison.Ordinal);
183	        Assert.Contains(".cluster-label", html, StringComparison.Ordinal);
184	    }
185	
186	    [Fact]
187	    public void Render_OverlayScript_UsesTransparentFill_NotNone()
188	    {
189	        // Same hit-testing hazard as the retired anchor node: fill:none is invisible to
190	        // pointer-events:visiblePainted hit-testing; the overlay rect must use a painted-but-
191	        // invisible transparent fill instead.
192	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
193	
194	        Assert.Contains("'transparent'", html, StringComparison.Ordinal);
195	    }
196	
197	    [Fact]
198	    public void Render_OverlayScript_SetsFillViaInlineStyle_NotTheFillAttribute()
199	    {
200	        // Real-browser regression (found live, not guessed): Mermaid's own generated stylesheet
201	        // carries a rule shaped like `#dag .cluster rect{fill:<theme color>;...}`. Since the
202	        // overlay rect is nested inside the .cluster group, that selector matches it too — and a
203	        // CSS class/tag selector beats a plain HTML presentation attribute, so
204	        // `rect.setAttribute('fill', 'transparent')` was silently overridden, painting a solid
205	        // theme-colored bar over the container's title text (confirmed via getComputedStyle:
206	        // attribute said "transparent", computed fill was the theme's cluster-background color).
207	        // An inline style (`rect.style.fill = ...`) wins over any external/embedded stylesheet
208	        // rule short of `!important`, so it reliably stays invisible. This test would have caught
209	        // the regression: `Assert.Contains("'transparent'")` alone passes for EITHER form.
210	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
211	
212	        Assert.Contains("rect.style.fill = 'transparent'", html, StringComparison.Ordinal);
213	        Assert.DoesNotContain("rect.setAttribute('fill'", html, StringComparison.Ordinal);
214	    }
215	
216	    [Fact]
217	    public void Render_OverlayScript_RunsAfterMermaidRenderResolves()
218	    {
219	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
220	
221	        int renderCall = html.IndexOf("await mermaid.render(", StringComparison.Ordinal);
222	        int overlayDefinition = html.IndexOf("function addTaskContainerOverlays", StringComparison.Ordinal);
223	        Assert.True(renderCall >= 0 && overlayDefinition >= 0, "both the render call and overlay function must be present");
224	
225	        // The overlay must be INVOKED after the render call (the definition itself may appear
226	        // earlier in the script — only invocation order matters for correctness).
227	        int overlayInvocation = html.IndexOf("addTaskContainerOverlays(", renderCall, StringComparison.Ordinal);
228	        Assert.True(overlayInvocation > renderCall, "the overlay must be applied to the SVG mermaid.render just produced");
229	    }
230	
231	    [Fact]
232	    public void Render_EmptyTaskFolderTargets_StillRendersValidPage()
233	    {
234	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
235	
236	        Assert.Contains("id=\"task-folder-targets\"", html, StringComparison.Ordinal);
237	        Assert.Contains("{}", html, StringComparison.Ordinal);
238	    }
239	
240	    // === long task-name title wrap-overflow fix (issue cluster-label-wrap-overflow) ====
241	    //
242	    // Mermaid always wraps a cluster's title <div> to a hardcoded 200px width (bundled
243	    // mermaid@11.4.1's plain flowchart cluster shape never overrides createText's width=200
244	    // default), and dagre's layout pass reserves the container's header-strip height BEFORE that
245	    // wrapped height is known — so a long kebab-case task name that wraps to 2+ lines prints past
246	    // the reserved strip, overlapping the first leaf guardrail/preflight box below it. No Mermaid
247	    // config knob avoids this (verified against the bundled 11.4.1 source). The fix re-wraps the
248	    // SAME text at up to the container's own (already wider) width post-render instead, verified
249	    // headless against 8+ real plans (40+ long task names, container widths ~230px-~1100px,
250	    // wraps of 2-3 lines): every case converged to one line with the same healthy gap a
251	    // never-wrapped label already has, and every already-fits label was left byte-for-byte
252	    // unchanged (including the whole golden hello-guardrails example).
253	
254	    [Fact]
255	    public void Render_DefinesFixWrappedClusterLabelsFunction()
256	    {
257	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
258	
259	        Assert.Contains("function fixWrappedClusterLabels(svgEl)", html, StringComparison.Ordinal);
260	    }
261	
262	    [Fact]
263	    public void Render_WrapFix_RunsAfterMermaidRenderResolves_AndBeforeTheOverlay()
264	    {
265	        // Ordering is load-bearing: addTaskContainerOverlays measures the label's CURRENT bbox to
266	        // size its click band, so a label the wrap fix already shrank back to one line must be
267	        // fixed FIRST, or the band would be sized for the original (possibly multi-line) wrap.
268	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
269	
270	        int renderCall = html.IndexOf("await mermaid.render(", StringComparison.Ordinal);
271	        int wrapFixInvocation = html.IndexOf("fixWrappedClusterLabels(", renderCall, StringComparison.Ordinal);
272	        int overlayInvocation = html.IndexOf("addTaskContainerOverlays(", renderCall, StringComparison.Ordinal);
273	
274	        Assert.True(renderCall >= 0 && wrapFixInvocation > renderCall && overlayInvocation > renderCall,
275	            "both post-render fixes must be invoked after the render call");
276	        Assert.True(wrapFixInvocation < overlayInvocation,
277	            "the wrap fix must run BEFORE the title-band overlay so the band reflects the corrected label size");
278	    }
279	
280	    [Fact]
281	    public void Render_WrapFix_MeasuresViaScrollWidth_NotGetBoundingClientRect()
282	    {
283	        // Regression guard for the exact measurement pitfall this fix's own investigation hit:
284	        // getBoundingClientRect() reports on-screen pixels affected by the page's pan-zoom
285	        // transform, which is misleading when compared against a foreignObject's local width/
286	        // height attributes. scrollWidth/scrollHeight are local layout-box measurements, in the
287	        // SAME coordinate system as those attributes, regardless of the current zoom level.
288	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
289	
290	        int fnStart = html.IndexOf("function fixWrappedClusterLabels", StringComparison.Ordinal);
291	        int fnEnd = html.IndexOf("\n}\n", fnStart, StringComparison.Ordinal);
292	        string fnBody = html[fnStart..fnEnd];
293	
294	        Assert.Contains("div.scrollWidth", fnBody, StringComparison.Ordinal);
295	        Assert.Contains("div.scrollHeight", fnBody, StringComparison.Ordinal);
296	        Assert.DoesNotContain("getBoundingClientRect", fnBody, StringComparison.Ordinal);
297	    }
298	
299	    [Fact]
300	    public void Render_WrapFix_NeverNarrowsBelowMermaidsOriginalWidth()
301	    {
302	        // The fix only ever WIDENS a label (fewer lines needs less height, never more) — it must
303	        // never choose a width narrower than what Mermaid already assigned, which would be a
304	        // regression risking MORE wrapping, not less.
305	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
306	
307	        Assert.Contains("Math.max(currentWidth, clusterBox.width - 16)", html, StringComparison.Ordinal);
308	    }
309	
310	    [Fact]
311	    public void Render_WrapFix_SkipsLabelsThatAlreadyFitOnOneLine()
312	    {
313	        // Short names (e.g. every task in the golden hello-guardrails example) must be left
314	        // completely untouched — this is the guard that makes that a no-op.
315	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
316	
317	        Assert.Contains("if (naturalWidth <= currentWidth) continue;", html, StringComparison.Ordinal);
318	    }
319	
320	    [Fact]
321	    public void Render_WrapFix_RevertsWhenWideningDoesNotReduceHeight()
322	    {
323	        // A container too narrow to help must fall back to Mermaid's original sizing rather than
324	        // risk an oddly-proportioned label — never regress relative to the pre-fix rendering.
325	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
326	
327	        Assert.Contains("if (newHeight >= currentHeight)", html, StringComparison.Ordinal);
328	        Assert.Contains("div.setAttribute('style', savedInline);", html, StringComparison.Ordinal);
329	    }
330	
331	    [Fact]
332	    public void Render_WrapFix_RecentersTheLabelOnTheSameMidpointAfterWidening()
333	    {
334	        // Mermaid centers the label group via translate(x - bbox.width / 2, y); widening without
335	        // re-centering would shift the (now wider) box off-center over the cluster.
336	        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
337	
338	        Assert.Contains("deltaCenter", html, StringComparison.Ordinal);
339	        Assert.Contains("label.setAttribute('transform',", html, StringComparison.Ordinal);
340	    }
341	
342	    // === live per-node status overlay (issue #219) =====================================
343	    //
344	    // While a `guardrails run` is in progress, diagram.html gains a small corner-anchored status
345	    // badge on each task container, preflight/guardrail leaf, and the plan-level Full Flight Checks
346	    // / Terminal Gate brackets: an animated spinner while running, a settled check/X/"?" glyph once
347	    // finished — driven by an OPTIONAL per-node status map plus an INDEPENDENT includeRefresh
348	    // toggle, mirroring LogSiteRenderer.IndexHtml(..., includeRefresh)'s during-run/final duality.
349	    //
350	    // These tests are structural/string-content assertions over the emitted HTML/JS (no headless
351	    // browser is configured in this repo — a documented Level-A gap): they prove the right markup
352	    // and data are EMITTED, not that a browser positions the badges pixel-correctly at runtime. The
353	    // four non-null-status tests are the intended TDD RED against the throwing stub — the
354	    // 02-implement-diagram-status-overlay-renderer task turns them green.
355	    //
356	    // Status-map ids use the SAME vocabulary MermaidRenderer emits (task containers `task_<base>`,
357	    // preflight/guardrail leaves `task_<base>_pf_<n>`/`task_<base>_gr_<n>`, and the two plan-level
358	    // brackets `plan_preflights`/`plan_guardrails`) so the post-render overlay script can position a
359	    // badge on the matching SVG node. All five status values are exercised.
360	    private static readonly IReadOnlyDictionary<string, string> SampleStatuses =
361	        new Dictionary<string, string>(StringComparer.Ordinal)
362	        {
363	            ["plan_preflights"] = "passed",       // Full Flight Checks bracket (top)
364	            ["task_root"] = "running",            // a task container, mid-run -> spinner
365	            ["task_root_pf_0"] = "passed",        // a preflight leaf check
366	            ["task_root_gr_0"] = "failed",        // a guardrail leaf check
367	            ["task_next"] = "pending",            // a not-yet-started task container
368	            ["plan_guardrails"] = "needs-human",  // Terminal Gate bracket (bottom)
369	        };
370	
371	    [Fact]
372	    public void Render_WithNullNodeStatuses_IsByteIdenticalToCurrentBehavior()
373	    {
374	        // The static `graph` command path (no live status) must be UNCHANGED by this feature: the
375	        // pre-existing three-argument overload and the new call passing nodeStatuses:null must
376	        // produce the exact same document, byte-for-byte — the golden fixtures
377	        // (examples/hello-guardrails, docs/plans/08-parallel-execution/diagram.html) are out of this
378	        // task's scope and must not need regenerating.
379	        string legacy = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
380	        string newNull = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, nodeStatuses: null);
381	
382	        Assert.Equal(legacy, newNull);
383	
384	        // ...and the static path carries NONE of the live-overlay markers. Each of these is absent
385	        // from today's template, so their absence pins the null path clean — a leak of the feature
386	        // into the static path (which would silently change every checked-in diagram.html) fails here.
387	        Assert.DoesNotContain("http-equiv=\"refresh\"", newNull, StringComparison.Ordinal);
388	        Assert.DoesNotContain("@keyframes", newNull, StringComparison.Ordinal);
389	        Assert.DoesNotContain("id=\"node-statuses\"", newNull, StringComparison.Ordinal);
390	    }
391	
392	    [Fact]
393	    public void Render_WithNodeStatuses_EmitsAMetaRefreshTag()
394	    {
395	        // A non-null status map with the default includeRefresh:true is the DURING-RUN diagram — it
396	        // must carry <meta http-equiv="refresh"> so a plain file:// view re-reads itself as the run
397	        // progresses (mirrors LogSiteRenderer's during-run index). The static (null) path must not.
398	        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);
399	        Assert.Contains("<meta http-equiv=\"refresh\"", live, StringComparison.Ordinal);
400	
401	        string stat = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, nodeStatuses: null);
402	        Assert.DoesNotContain("http-equiv=\"refresh\"", stat, StringComparison.Ordinal);
403	    }
404	
405	    [Fact]
406	    public void Render_WithNodeStatusesAndIncludeRefreshFalse_OmitsTheMetaRefreshTag()
407	    {
408	        // The FINAL settled render (wired at run-end by 06-wire-diagramobserver-into-runcommand):
409	        // nodeStatuses is STILL non-null (every node shows its final settled status) but
410	        // includeRefresh:false, so the auto-reload tag is dropped — the page is done refreshing. The
411	        // status overlay itself must STILL be emitted (the refresh tag and the overlay are independent).
412	        string settled = HtmlDiagramRenderer.Render(
413	            Source, Hash, OneTarget, SampleStatuses, includeRefresh: false);
414	
415	        Assert.DoesNotContain("http-equiv=\"refresh\"", settled, StringComparison.Ordinal);
416	        // still a live-status document — the overlay data is present regardless of includeRefresh.
417	        Assert.Contains("id=\"node-statuses\"", settled, StringComparison.Ordinal);
418	        Assert.Contains("\"task_root\"", settled, StringComparison.Ordinal);
419	    }
420	
421	    [Fact]
422	    public void Render_WithNodeStatuses_EmitsAnOverlayForEachStatusEntry()
423	    {
424	        // Every node id in the status map must be referenced by the overlay-rendering logic — the
425	        // map is embedded as a JSON side-table (mirroring the task-folder-targets side-table) keyed
426	        // by the SAME Mermaid node/container ids, so the post-render script can position a badge on
427	        // each matching SVG node. Assert the QUOTED (JSON-key) form: a bare-word check would false-
428	        // positive on ids like `plan_guardrails` that ALREADY appear in a code comment in today's
429	        // template — only the emitted status map produces the quoted form.
430	        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);
431	
432	        foreach (string nodeId in SampleStatuses.Keys)
433	        {
434	            Assert.Contains($"\"{nodeId}\"", live, StringComparison.Ordinal);
435	        }
436	    }
437	
438	    [Fact]
439	    public void Render_WithRunningStatus_EmitsASpinnerClass_AndSettledStatusesEmitAGlyph()
440	    {
441	        // "running" must render an ANIMATED spinner (a CSS @keyframes rotation — no external
442	        // image/GIF dependency), visibly distinct from a settled status's STATIC glyph (check / X /
443	        // "?"). Assert both the spinner animation + its dedicated class AND at least one settled
444	        // glyph are present; the spinner marker (a CSS class) is inherently distinct from the glyph
445	        // characters, so a spinner can never be mistaken for a settled state.
446	        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);
447	
448	        // spinner: a CSS keyframes rotation + a dedicated class (neither exists in the static template).
449	        Assert.Contains("@keyframes", live, StringComparison.Ordinal);
450	        Assert.Contains("status-spinner", live, StringComparison.Ordinal);
451	
452	        // settled glyphs: `passed` -> U+2713 CHECK MARK, `failed` -> U+2717 BALLOT X (both present in
453	        // SampleStatuses). Written as literal UTF-8 glyphs; this file is valid UTF-8, which Roslyn's
454	        // BOM-less source detection decodes as UTF-8, so the literals compile to exactly these chars.
455	        Assert.Contains("✓", live, StringComparison.Ordinal);
456	        Assert.Contains("✗", live, StringComparison.Ordinal);
457	    }
458	}
