8	namespace Guardrails.Cli.Ui;
9	
10	/// <summary>
11	/// The SINGLE renderer for the log viewer's HTML — the LIVE <see cref="LogServer"/> (dynamic pages
12	/// polled client-side), the DURING-RUN static site (rewritten on the fly as tasks settle, issue
13	/// #141 item 2), and the DURABLE post-hoc export (<c>guardrails logs --export</c>, SSOT §12.3) all
14	/// consume it, so there is no forked look-alike (#103 Request 2). They share the page SHELL (CSS +
15	/// layout + the same status colours); they differ ONLY in the index's per-task link target and
16	/// whether the index auto-refreshes:
17	/// <list type="bullet">
18	///   <item>DURING-RUN index — a <c>&lt;meta http-equiv="refresh"&gt;</c> so a <c>file://</c> view
19	///     re-reads it as the harness rewrites it; a RUNNING task links to the LIVE server URL (a click
20	///     tails it), a settled/with-attempts task links to its static <c>&lt;taskId&gt;/index.html</c>,
21	///     a pending/no-attempts task is plain text.</item>
22	///   <item>FINAL / <c>--export</c> index — NO refresh, ALL links static (durable, non-flickering).</item>
23	/// </list>
24	///
25	/// <para>The static site is written next to the artifacts it renders, under the <c>logs/&lt;runId&gt;/</c>
26	/// audit tree (NEVER <c>state/</c>, which is mutable run state): one <c>index.html</c> per task plus a
27	/// site <c>index.html</c>. It is non-authored audit (excluded from <c>guardrails.baseline</c>, like
28	/// <c>diagram.html</c>) and is cleared with the rest of <c>logs/</c> by <c>--fresh</c>.</para>
29	/// </summary>
30	public static class LogSiteRenderer
31	{
32	    // The shared page CSS (dark theme + the status-word colours). The live LogServer templates and the
33	    // static export both embed THIS constant, so a visual change lands in one place — the renderer-drift
34	    // trap the project already solved for diagram.md / diagram.html.
35	    public const string SharedStyle = """
36	  body { font-family: system-ui, sans-serif; margin: 1.5rem; background: #0b0f14; color: #d6deeb; }
37	  h1 { font-size: 1.2rem; }
38	  h2 { font-size: 1rem; color: #8aa0b3; margin-top: 1.6rem; }
39	  p { color: #8aa0b3; }
40	  a { color: #7fdbff; text-decoration: none; }
41	  a:hover { text-decoration: underline; }
42	  .bar { color: #8aa0b3; margin-bottom: .8rem; }
43	  table { border-collapse: collapse; margin-top: 1rem; width: 100%; }
44	  td, th { padding: .45rem .8rem; border-bottom: 1px solid #1c2733; text-align: left; }
45	  th { color: #8aa0b3; font-weight: 600; }
46	  select { background: #121a24; color: #d6deeb; border: 1px solid #243343; border-radius: 4px; padding: .2rem .4rem; }
47	  td.status, span.status { font-weight: 600; }
48	  .status[data-status="succeeded"], .status[data-status="skipped"] { color: #3fb950; }
49	  .status[data-status="needs-human"], .status[data-status="failed"] { color: #f85149; }
50	  .status[data-status="running"] { color: #d29922; }
51	  .status[data-status="pending"], .status[data-status="blocked"], .status[data-status="unknown"] { color: #8aa0b3; }
52	  .empty, option.empty { color: #6b7a8d; }
53	  pre { background: #06090d; border: 1px solid #1c2733; border-radius: 6px; padding: 1rem;
54	        white-space: pre-wrap; word-break: break-word; font-size: .82rem; line-height: 1.35;
55	        max-height: 70vh; overflow: auto; }
56	""";
57	
58	    // Per-attempt file the static page inlines FIRST (mirrors LogServer's PreferenceOrder): the groomed
59	    // transcript leads, then the raw stream, then script stdout.
60	    private static readonly string[] PreferenceOrder =
61	        ["transcript.md", "claude-stream.jsonl", "action-stdout.log"];
62	
63	    private static readonly Encoding Utf8NoBom = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);
64	
65	    /// <summary>
66	    /// The per-task link target an index renders for one task. <see cref="StaticPage"/> points at the
67	    /// task's static <c>&lt;taskId&gt;/index.html</c>; <see cref="Live"/> carries an absolute live-server
68	    /// URL whose click tails the task; <see cref="PlainText"/> renders the id as plain text (no anchor).
69	    /// </summary>
70	    public enum LinkKind
71	    {
72	        /// <summary>Plain text — no anchor (a pending / no-attempts task offline).</summary>
73	        PlainText,
74	
75	        /// <summary>A relative link to the task's static <c>&lt;taskId&gt;/index.html</c>.</summary>
76	        StaticPage,
77	
78	        /// <summary>An absolute live-server URL (a click tails the running task).</summary>
79	        Live,
80	    }
81	
82	    /// <summary>How an index renders one task: the link target kind plus the URL for a <see cref="LinkKind.Live"/> link.</summary>
83	    public readonly record struct IndexLink(LinkKind Kind, string? LiveUrl = null)
84	    {
85	        /// <summary>A plain-text (non-link) cell.</summary>
86	        public static readonly IndexLink Plain = new(LinkKind.PlainText);
87	
88	        /// <summary>A relative link to the task's static page.</summary>
89	        public static readonly IndexLink Static = new(LinkKind.StaticPage);
90	
91	        /// <summary>An absolute live-server link to tail the running task.</summary>
92	        public static IndexLink LiveTo(string url) => new(LinkKind.Live, url);
93	    }
94	
95	    /// <summary>
96	    /// Export the whole DURABLE static site for one run into <paramref name="logsRoot"/>
97	    /// (<c>&lt;planDir&gt;/logs/&lt;runId&gt;/</c>): a per-task <c>index.html</c> for every task that
98	    /// has attempts on disk, plus a site <c>index.html</c> with NO refresh and ALL-static links. Idempotent
99	    /// — regenerates everything each call (like <c>guardrails graph</c>). Returns the path to the site index.
100	    /// A task with no attempts on disk is listed (as plain text, not a link) in the index but writes no page.
101	    /// This is the post-hoc <c>logs --export</c> surface (SSOT §12.3) — preserved verbatim.
102	    /// </summary>
103	    public static string ExportSite(string logsRoot, IReadOnlyList<TaskNode> tasks, JournalDocument journal)
104	    {
105	        Directory.CreateDirectory(logsRoot);
106	
107	        foreach (TaskNode task in tasks)
108	        {
109	            WriteTaskPageIfHasAttempts(logsRoot, task);
110	        }
111	
112	        // Durable export: a settled-with-attempts task links to its static page, a not-yet-run task is
113	        // plain text. No live URLs, no meta-refresh (#103 / SSOT §12.3).
114	        string index = IndexHtml(
115	            journal.RunId,
116	            tasks,
117	            statusResolver: id => StatusWord(journal, id),
118	            linkResolver: id => AttemptDirs(logsRoot, id).Count > 0 ? IndexLink.Static : IndexLink.Plain,
119	            includeRefresh: false);
120	
121	        string indexPath = Path.Combine(logsRoot, "index.html");
122	        AtomicFile.WriteAllText(indexPath, index);
123	        return indexPath;
124	    }
125	
126	    /// <summary>
127	    /// Render and atomically write the during-run / final site index to
128	    /// <c>&lt;logsRoot&gt;/index.html</c> (issue #141 item 2). The caller supplies the status word and
129	    /// the per-task link target so the SAME renderer serves the during-run index (live URLs + refresh)
130	    /// and the settled final index (all static, no refresh). <paramref name="includeRefresh"/> is true
131	    /// while the run is in flight (so a <c>file://</c> browser re-reads it as it is rewritten) and false
132	    /// for the durable final write. Atomic temp+rename so a browser never reads a half-written file.
133	    /// Returns the path written.
134	    /// </summary>
135	    public static string WriteIndex(
136	        string logsRoot,
137	        string runId,
138	        IReadOnlyList<TaskNode> tasks,
139	        Func<string, string> statusResolver,
140	        Func<string, IndexLink> linkResolver,
141	        bool includeRefresh)
142	    {
143	        string index = IndexHtml(runId, tasks, statusResolver, linkResolver, includeRefresh);
144	        string indexPath = Path.Combine(logsRoot, "index.html");
145	        AtomicFile.WriteAllText(indexPath, index);
146	        return indexPath;
147	    }
148	
149	    /// <summary>
150	    /// Atomically write one task's static page (<c>&lt;logsRoot&gt;/&lt;taskId&gt;/index.html</c>) with its
151	    /// final inlined logs and a Source section, when the task has attempts on disk (issue #141 item 2).
152	    /// No-op when the task has no attempts yet. <paramref name="logsRoot"/> is the run's
153	    /// <c>logs/&lt;runId&gt;/</c> tree. Atomic temp+rename so a browser viewing the page never reads a torn file.
154	    /// </summary>
155	    public static void WriteTaskPageIfHasAttempts(string logsRoot, TaskNode task)
156	    {
157	        if (AttemptDirs(logsRoot, task.Id).Count == 0)
158	        {
159	            return; // nothing to render — task never ran / not started; it stays a non-link in the index
160	        }
161	
162	        string page = TaskPage(logsRoot, task);
163	        AtomicFile.WriteAllText(Path.Combine(logsRoot, task.Id, "index.html"), page);
164	    }
165	
166	    // --- site index (projection of status + link target) ------------------------------------
167	
168	    /// <summary>
169	    /// The site landing page: every task with its status word and a link target chosen by the caller's
170	    /// <paramref name="linkResolver"/> (static page / live URL / plain text). Regenerated on every write
171	    /// (never appended). When <paramref name="includeRefresh"/> is true a <c>meta refresh</c> makes a
172	    /// <c>file://</c> view re-read the file as the harness rewrites it ("updated on the fly"); the durable
173	    /// final / <c>--export</c> index omits it.
174	    /// </summary>
175	    private static string IndexHtml(
176	        string runId,
177	        IReadOnlyList<TaskNode> tasks,
178	        Func<string, string> statusResolver,
179	        Func<string, IndexLink> linkResolver,
180	        bool includeRefresh)
181	    {
182	        var rows = new StringBuilder();
183	        foreach (TaskNode task in tasks)
184	        {
185	            string status = statusResolver(task.Id);
186	            string cell = IndexCell(task.Id, linkResolver(task.Id));
187	
188	            rows.Append("<tr><td>").Append(cell).Append("</td>")
189	                .Append("<td class=\"status\" data-status=\"").Append(Enc(status)).Append("\">")
190	                .Append(Enc(status)).Append("</td>")
191	                .Append("<td>").Append(Enc(task.Description)).Append("</td></tr>");
192	        }
193	
194	        // The meta-refresh is the "no server needed" mechanism for the during-run file:// view (#141):
195	        // the browser re-reads index.html every 2s, so a click after a task settles finds the static page.
196	        string refresh = includeRefresh
197	            ? "\n<meta http-equiv=\"refresh\" content=\"2\">"
198	            : string.Empty;
199	
200	        string note = includeRefresh
201	            ? "Live run — this page refreshes itself. Running tasks tail their log; settled tasks link to a static page; not-yet-run tasks are plain text."
202	            : "Static export of this run. Settled tasks link to their inlined log page; not-yet-run tasks are plain text.";
203	
204	        return $"""
205	<!doctype html>
206	<html lang="en">
207	<head>
208	<meta charset="utf-8">
209	<meta name="viewport" content="width=device-width, initial-scale=1">{refresh}
210	<title>Guardrails run {Enc(runId)} — log site</title>
211	<style>
212	{SharedStyle}
213	</style>
214	</head>
215	<body>
216	<h1>Guardrails run — task logs</h1>
217	<p>{Enc(note)}</p>
218	<table>
219	<thead><tr><th>Task</th><th>Status</th><th>Description</th></tr></thead>
220	<tbody>
221	{rows}
222	</tbody>
223	</table>
224	</body>
225	</html>
226	""";
227	    }
228	
229	    private static string IndexCell(string taskId, IndexLink link) => link.Kind switch
230	    {
231	        LinkKind.StaticPage => $"<a href=\"{Uri.EscapeDataString(taskId)}/index.html\">{Enc(taskId)}</a>",
232	        LinkKind.Live when link.LiveUrl is { } url => $"<a href=\"{Enc(url)}\">{Enc(taskId)}</a>",
233	        _ => Enc(taskId), // PlainText, or a Live link with no URL (no server) → not a link
234	    };
235	
236	    // --- per-task page (inlined attempts + source) ------------------------------------------
237	
238	    /// <summary>
239	    /// One task's static page: every attempt on disk is rendered into its own <c>&lt;section
240	    /// data-attempt="N"&gt;</c> (issue #206), each carrying a file <c>&lt;select&gt;</c> combobox that
241	    /// toggles between that attempt's files, all inlined as hidden <c>&lt;pre class="filebody"&gt;</c>
242	    /// blocks (the PREFERRED file — transcript, else raw stream, else action stdout — shown first).
243	    /// Whenever there is at least one attempt, an attempt <c>&lt;select id="attemptselect"&gt;</c> — always
244	    /// rendered, matching the live viewer's attempt dropdown (<see cref="LogServer"/>: its
245	    /// <c>&lt;select id="attempt"&gt;</c> is unconditionally present in the page shell, even with a single
246	    /// attempt — populated with just one option) — lets the user pick which attempt's section is visible;
247	    /// every attempt's markup stays inlined in the one exported file (a <c>file://</c> page can't fetch
248	    /// siblings), the dropdown only shows/hides <c>&lt;section&gt;</c>s. Default selection is the LATEST
249	    /// attempt, matching the live viewer's default. (Before issue #241's follow-up, a single-attempt task
250	    /// rendered no dropdown at all — an inconsistency with the live viewer, caught live during a real
251	    /// dogfood: a user who watched a task pass on attempt 1 in the live view, then checked the exported
252	    /// static page afterward, found the dropdown had disappeared.) The existing per-attempt file combobox
253	    /// is untouched: it stays nested inside its attempt's <c>&lt;section&gt;</c> and is shown/hidden as
254	    /// part of it. A Source section (action file + guardrail scripts from <c>&lt;task.Directory&gt;</c>,
255	    /// #141 item 3) and the "← all tasks" back-link follow, unchanged.
256	    ///
257	    /// <para>Trade-off (#145 Feature 2, extended by #206): inlining every attempt's every file bloats the
258	    /// page by the full size of each raw stream. Accepted for the audit/demo use — a <c>file://</c> page
259	    /// has no other way to show siblings — so it is deliberately uncapped.</para>
260	    /// </summary>
261	    private static string TaskPage(string logsRoot, TaskNode task)
262	    {
263	        IReadOnlyList<int> attempts = AttemptNumbers(logsRoot, task.Id);
264	        var sections = new StringBuilder();
265	
266	        // The latest attempt (highest number) is the default-visible one, matching the live viewer's
267	        // "follow latest" default (LogServer's TaskTemplate: `asel.value = ... d.attempt`).
268	        int latest = attempts.Count > 0 ? attempts[^1] : 0;
269	
270	        if (attempts.Count > 0)
271	        {
272	            AppendAttemptSelect(sections, attempts, latest);
273	        }
274	
275	        foreach (int n in attempts)
276	        {
277	            string attemptDir = Path.Combine(logsRoot, task.Id, $"attempt-{n}");
278	            IReadOnlyList<string> files = AttemptFiles(attemptDir);
279	            string? preferred = PreferenceOrder.FirstOrDefault(files.Contains) ?? files.FirstOrDefault();
280	            bool visible = n == latest;
281	
282	            sections.Append("<section class=\"attempt\" data-attempt=\"").Append(n).Append('"')
283	                .Append(visible ? string.Empty : " hidden").Append('>');
284	            sections.Append("<h2>attempt ").Append(n).Append("</h2>");
285	            AppendAttemptFiles(sections, attemptDir, n, files, preferred);
286	            sections.Append("</section>");
287	        }
288	
289	        if (attempts.Count == 0)
290	        {
291	            sections.Append("<pre>no attempts captured</pre>");
292	        }
293	
294	        sections.Append(SourceSection(logsRoot, task));
295	
296	        return $"""
297	<!doctype html>
298	<html lang="en">
299	<head>
300	<meta charset="utf-8">
301	<meta name="viewport" content="width=device-width, initial-scale=1">
302	<title>{Enc(task.Id)} — Guardrails log</title>
303	<style>
304	{SharedStyle}
305	</style>
306	</head>
307	<body>
308	<h1>{Enc(task.Id)}</h1>
309	<div class="bar"><a href="../index.html">&larr; all tasks</a> &middot; {Enc(task.Description)}</div>
310	{sections}
311	{FileToggleScript}
312	</body>
313	</html>
314	""";
315	    }
316	
317	    /// <summary>
318	    /// Render the attempt-level <c>&lt;select id="attemptselect"&gt;</c> (issue #206): one option per
319	    /// attempt (oldest first, matching the on-page section order), the <paramref name="latest"/> attempt
320	    /// pre-selected — mirroring the live viewer's "default to latest" behaviour. Emitted whenever a task
321	    /// has at least one attempt (issue #241) — including exactly one — so the static export always
322	    /// matches the live viewer's page shell, which unconditionally carries an attempt <c>&lt;select&gt;</c>
323	    /// regardless of how many attempts exist.
324	    /// </summary>
325	    private static void AppendAttemptSelect(StringBuilder sections, IReadOnlyList<int> attempts, int latest)
326	    {
327	        sections.Append("<div class=\"bar\">attempt <select id=\"attemptselect\" class=\"attemptselect\">");
328	        foreach (int n in attempts)
329	        {
330	            string sel = n == latest ? " selected" : string.Empty;
331	            sections.Append("<option value=\"").Append(n).Append('"').Append(sel).Append('>')
332	                .Append("attempt ").Append(n).Append("</option>");
333	        }
334	
335	        sections.Append("</select></div>");
336	    }
337	
338	    /// <summary>
339	    /// Render one attempt's file combobox: a <c>&lt;select&gt;</c> listing every file in the attempt (the
340	    /// <paramref name="preferred"/> one pre-selected; zero-byte files <c>empty</c>-marked + " (empty)"),
341	    /// then every file's content inlined as a hidden <c>&lt;pre class="filebody"&gt;</c> (only the preferred
342	    /// one shown). All elements carry <c>data-attempt="N"</c> + <c>data-file="..."</c> so the toggle script
343	    /// scopes show/hide to THIS attempt — multiple attempts on the page never collide. Content is
344	    /// HTML-encoded (arbitrary logs / LLM output) via <see cref="Enc"/> and read through the shared-handle
345	    /// <see cref="ReadOrEmpty"/>. An attempt with no files shows a single "no output captured" body.
346	    /// </summary>
347	    private static void AppendAttemptFiles(
348	        StringBuilder sections, string attemptDir, int attempt, IReadOnlyList<string> files, string? preferred)
349	    {
350	        if (files.Count == 0)
351	        {
352	            sections.Append("<div class=\"bar\">showing <code>(no files)</code></div>");
353	            sections.Append("<pre class=\"filebody\" data-attempt=\"").Append(attempt)
354	                .Append("\" data-file=\"\">").Append(Enc("no output captured")).Append("</pre>");
355	            return;
356	        }
357	
358	        // The file <select>: one option per file, scoped to this attempt; the preferred file is selected.
359	        sections.Append("<div class=\"bar\">file <select class=\"fileselect\" data-attempt=\"").Append(attempt).Append("\">");
360	        foreach (string f in files)
361	        {
362	            bool empty = IsZeroByte(Path.Combine(attemptDir, f));
363	            string label = empty ? $"{f} (empty)" : f;
364	            string sel = string.Equals(f, preferred, StringComparison.Ordinal) ? " selected" : string.Empty;
365	            string cls = empty ? " class=\"empty\"" : string.Empty;
366	            sections.Append("<option").Append(cls)
367	                .Append(" data-attempt=\"").Append(attempt).Append('"')
368	                .Append(" data-file=\"").Append(Enc(f)).Append('"').Append(sel).Append('>')
369	                .Append(Enc(label)).Append("</option>");
370	        }
371	
372	        sections.Append("</select></div>");
373	
374	        // Inline every file's content as a hidden <pre>; only the preferred file's block is shown. A
375	        // file:// page can't fetch siblings, so all bodies are baked in and the <select> toggles them
376	        // (no fetch). Encode every body — arbitrary logs / LLM output. (Trade-off: this bloats the page
377	        // by the full raw-stream size; accepted for audit/demo — see TaskPage's remarks. Uncapped.)
378	        foreach (string f in files)
379	        {
380	            string raw = ReadOrEmpty(Path.Combine(attemptDir, f));
381	            bool shown = string.Equals(f, preferred, StringComparison.Ordinal);
382	            string hidden = shown ? string.Empty : " hidden";
383	            sections.Append("<pre class=\"filebody\"").Append(hidden)
384	                .Append(" data-attempt=\"").Append(attempt).Append('"')
385	                .Append(" data-file=\"").Append(Enc(f)).Append("\">")
386	                .Append(Enc(raw.Length > 0 ? raw : "no output captured")).Append("</pre>");
387	        }
388	    }
389	
390	    /// <summary>
391	    /// The vanilla-JS toggle that wires every per-attempt file <c>&lt;select&gt;</c> AND (#206) the
392	    /// attempt-level <c>&lt;select id="attemptselect"&gt;</c>, reusing the SAME show/hide mechanism for
393	    /// both — no second pattern invented: on change, hide every element for that scope and unhide the one
394	    /// whose data attribute matches the selected option. The file toggle hides <c>.filebody</c> elements
395	    /// scoped by <c>data-attempt</c> so attempts don't collide; the attempt toggle hides
396	    /// <c>section.attempt</c> elements scoped by <c>data-attempt</c> (the nested file combobox travels
397	    /// with its parent section — switching attempts shows/hides it along with everything else in the
398	    /// section, untouched). Pure DOM — NO fetch — because this is a static <c>file://</c> page (a fetch of
399	    /// a sibling file is blocked offline).
400	    /// </summary>
401	    private const string FileToggleScript = """
402	<script>
403	(function () {
404	  document.querySelectorAll('select.fileselect').forEach(function (sel) {
405	    sel.addEventListener('change', function () {
406	      var attempt = sel.getAttribute('data-attempt');
407	      var file = sel.options[sel.selectedIndex].getAttribute('data-file');
408	      document.querySelectorAll('pre.filebody[data-attempt="' + attempt + '"]').forEach(function (pre) {
409	        pre.hidden = pre.getAttribute('data-file') !== file;
410	      });
411	    });
412	  });
413	
414	  var attemptSel = document.getElementById('attemptselect');
415	  if (attemptSel) {
416	    attemptSel.addEventListener('change', function () {
417	      var attempt = attemptSel.options[attemptSel.selectedIndex].value;
418	      document.querySelectorAll('section.attempt').forEach(function (section) {
419	        section.hidden = section.getAttribute('data-attempt') !== attempt;
420	      });
421	    });
422	  }
423	})();
424	</script>
425	""";
426	
427	    /// <summary>
428	    /// The static "Source" section (#141 item 3): a list of relative <c>file://</c> links from the task's
429	    /// static page (<c>logs/&lt;runId&gt;/&lt;taskId&gt;/index.html</c>) back to the action file and every
430	    /// guardrail script under <c>&lt;task.Directory&gt;</c>, so a user whose guardrail threw can open the
431	    /// script with one click. Paths are computed with <see cref="Path.GetRelativePath"/> (browsers open
432	    /// text inline). The guardrail scripts are the motivating case, so they get their own sub-list.
433	    /// </summary>
434	    private static string SourceSection(string logsRoot, TaskNode task)
435	    {
436	        // Relative from the page that links them: logs/<runId>/<taskId>/index.html lives in this dir.
437	        string fromDir = Path.Combine(logsRoot, task.Id);
438	
439	        var sb = new StringBuilder();
440	        sb.Append("<h2>Source</h2>");
441	
442	        SourceFile action = ActionSource(task);
443	        sb.Append("<div class=\"bar\">action: ").Append(SourceLink(fromDir, action)).Append("</div>");
444	
445	        IReadOnlyList<SourceFile> guardrails = GuardrailSources(task);
446	        if (guardrails.Count > 0)
447	        {
448	            sb.Append("<div class=\"bar\">guardrails: ");
449	            sb.Append(string.Join(" · ", guardrails.Select(g => SourceLink(fromDir, g))));
450	            sb.Append("</div>");
451	        }
452	
453	        return sb.ToString();
454	    }
455	
456	    private static string SourceLink(string fromDir, SourceFile file)
457	    {
458	        string rel = Path.GetRelativePath(fromDir, file.Path).Replace('\\', '/');
459	        bool empty = IsZeroByte(file.Path);
460	        string label = empty ? $"{Enc(file.Label)} (empty)" : Enc(file.Label);
461	        string cls = empty ? " class=\"empty\"" : string.Empty;
462	        // Encode each path segment so spaces / unusual chars survive as a file:// URL, but keep the
463	        // slashes literal so the relative path stays navigable.
464	        string href = string.Join('/', rel.Split('/').Select(Uri.EscapeDataString));
465	        return $"<a{cls} href=\"{href}\">{label}</a>";
466	    }
467	
468	    // --- source discovery (shared with the live LogServer) ----------------------------------
469	
470	    /// <summary>A source file the viewers surface: its absolute path plus the label shown to the user.</summary>
471	    public readonly record struct SourceFile(string Name, string Label, string Path);
472	
473	    /// <summary>The task's action file (absolute path + label), from <see cref="ActionDefinition.Path"/>.</summary>
474	    public static SourceFile ActionSource(TaskNode task)
475	    {
476	        string name = System.IO.Path.GetFileName(task.Action.Path);
477	        return new SourceFile(name, name, task.Action.Path);
478	    }
479	
480	    /// <summary>
481	    /// The task's guardrail source files (absolute path + label), in filename sort order. Each guardrail's
482	    /// script is included; an optional <c>&lt;name&gt;.json</c> metadata sidecar (SSOT §4.1) is included
483	    /// too when present, so the user sees the full guardrail definition. Ordinal-sorted by label.
484	    /// </summary>
485	    public static IReadOnlyList<SourceFile> GuardrailSources(TaskNode task)
486	    {
487	        var files = new List<SourceFile>();
488	        foreach (GuardrailDefinition guardrail in task.Guardrails)
489	        {
490	            string scriptName = System.IO.Path.GetFileName(guardrail.Path);
491	            files.Add(new SourceFile(scriptName, scriptName, guardrail.Path));
492	
493	            // The optional metadata sidecar (SSOT §4.1) lives beside the script as <name>.json.
494	            string sidecar = System.IO.Path.ChangeExtension(guardrail.Path, ".json");
495	            if (File.Exists(sidecar))
496	            {
497	                string sidecarName = System.IO.Path.GetFileName(sidecar);
498	                files.Add(new SourceFile(sidecarName, sidecarName, sidecar));
499	            }
500	        }
501	
502	        return files.OrderBy(f => f.Label, StringComparer.Ordinal).ToList();
503	    }
504	
505	    // --- helpers ----------------------------------------------------------------------------
506	
507	    private static string StatusWord(JournalDocument journal, string taskId) =>
508	        journal.Tasks.TryGetValue(taskId, out TaskJournalEntry? entry) ? StatusText(entry.Status) : "unknown";
509	
510	    /// <summary>Map a journal status to the SSOT status word shown in the UI (shared with the live viewer).</summary>
511	    public static string StatusText(JournalTaskStatus status) => status switch
512	    {
513	        JournalTaskStatus.Pending => "pending",
514	        JournalTaskStatus.Running => "running",
515	        JournalTaskStatus.Succeeded => "succeeded",
516	        JournalTaskStatus.NeedsHuman => "needs-human",
517	        JournalTaskStatus.Blocked => "blocked",
518	        JournalTaskStatus.Failed => "failed",
519	        _ => status.ToString()
520	    };
521	
522	    private static IReadOnlyList<string> AttemptDirs(string logsRoot, string taskId)
523	    {
524	        string taskDir = Path.Combine(logsRoot, taskId);
525	        if (!Directory.Exists(taskDir))
526	        {
527	            return Array.Empty<string>();
528	        }
529	
530	        return Directory.EnumerateDirectories(taskDir)
531	            .Where(d => Path.GetFileName(d).StartsWith("attempt-", StringComparison.Ordinal))
532	            .ToList();
533	    }
534	
535	    private static IReadOnlyList<int> AttemptNumbers(string logsRoot, string taskId)
536	    {
537	        var numbers = new List<int>();
538	        foreach (string dir in AttemptDirs(logsRoot, taskId))
539	        {
540	            string leaf = Path.GetFileName(dir);
541	            if (int.TryParse(leaf.AsSpan("attempt-".Length), out int n))
542	            {
543	                numbers.Add(n);
544	            }
545	        }
546	
547	        numbers.Sort();
548	        return numbers;
549	    }
550	
551	    private static IReadOnlyList<string> AttemptFiles(string attemptDir) =>
552	        Directory.Exists(attemptDir)
553	            ? Directory.EnumerateFiles(attemptDir)
554	                .Select(Path.GetFileName)
555	                .Where(n => n is not null)
556	                .Select(n => n!)
557	                .OrderBy(n => n, StringComparer.Ordinal)
558	                .ToList()
559	            : Array.Empty<string>();
560	
561	    /// <summary>True when the file exists and is zero bytes (an empty stdout/stderr capture, #141 item 4).</summary>
562	    private static bool IsZeroByte(string path)
563	    {
564	        try
565	        {
566	            var info = new FileInfo(path);
567	            return info.Exists && info.Length == 0;
568	        }
569	        catch (IOException)
570	        {
571	            return false; // never let a stat failure abort the render
572	        }
573	    }
574	
575	    /// <summary>Read a file with a fully shared handle (a producer may still be writing); empty if absent.</summary>
576	    private static string ReadOrEmpty(string path)
577	    {
578	        if (!File.Exists(path))
579	        {
580	            return string.Empty;
581	        }
582	
583	        try
584	        {
585	            using var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
586	            using var reader = new StreamReader(fs, Encoding.UTF8);
587	            return reader.ReadToEnd();
588	        }
589	        catch (IOException)
590	        {
591	            return string.Empty; // never let an unreadable artifact abort the whole export
592	        }
593	    }
594	
595	    private static string Enc(string s) => WebUtility.HtmlEncode(s);
596	}
