public static string Render(
    string mermaidSource, string sourceHash, IReadOnlyDictionary<string, string> taskFolderTargets,
    IReadOnlyDictionary<string, string>? nodeStatuses = null, bool includeRefresh = true)
{
    ArgumentNullException.ThrowIfNull(mermaidSource);
    ArgumentException.ThrowIfNullOrEmpty(sourceHash);
    ArgumentNullException.ThrowIfNull(taskFolderTargets);

    // Newline-normalize so the file is byte-identical across OSes (mirrors the renderer/hash).
    string source = mermaidSource
        .Replace("\r\n", "\n", StringComparison.Ordinal)
        .Replace("\r", "\n", StringComparison.Ordinal)
        .TrimEnd('\n');

    // Encoder that escapes NOTHING beyond what JSON strictly requires (default System.Text.Json
    // escapes '<', '>', '&', etc. as \uXXXX for HTML safety, which is unnecessary here — the
    // JSON sits inside a <script type="application/json"> element, read back via textContent,
    // exactly like the Mermaid source above — but using the unsafe-relaxed encoder keeps a
    // task-id containing e.g. "&" readable in the raw HTML source without changing behavior).
    string targetsJson = JsonSerializer.Serialize(taskFolderTargets, new JsonSerializerOptions
    {
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    });

    string html = Template
        .Replace("__SOURCE_SHA256__", sourceHash, StringComparison.Ordinal)
        .Replace("__GRAPH_SOURCE__", source, StringComparison.Ordinal)
        .Replace("__TASK_FOLDER_TARGETS__", targetsJson, StringComparison.Ordinal);

    // Live-run status overlay (issue #219) is OPTIONAL: when nodeStatuses is null (the static
    // `graph` command, which never runs live) the template is emitted UNCHANGED, so the output
    // stays byte-identical to the pre-#219 three-argument render. When provided, inject the
    // per-node status badges + CSS, the node-statuses side-table, and — when includeRefresh — the
    // auto-reload meta tag (see InjectStatusOverlay).
    if (nodeStatuses is not null)
    {
        html = InjectStatusOverlay(html, nodeStatuses, includeRefresh);
    }

    // Normalize the full output — the template raw-string literal (and the injected blocks above)
    // pick up \r\n when the file is checked out with CRLF on Windows; the mermaid source is
    // already normalized above.
    return html
        .Replace("\r\n", "\n", StringComparison.Ordinal)
        .Replace("\r", "\n", StringComparison.Ordinal);
}

/// <summary>
/// Inject the live-run status overlay (issue #219) into the base <paramref name="html"/>: the
/// per-node status-badge markup + CSS, the <c>#node-statuses</c> JSON side-table, and — when
/// <paramref name="includeRefresh"/> — the <c>&lt;meta http-equiv="refresh"&gt;</c> auto-reload
/// tag. Called ONLY on the non-null path (see <see cref="Render"/>), so the static-graph output is
/// left byte-identical.
/// </summary>
/// <remarks>
/// Mirrors the existing title-band overlay's post-render-script technique: the badges are HTML
/// overlay <c>&lt;div&gt;</c>s (like <c>#bar</c>/<c>#legend</c>) rendered OUTSIDE the SVG and
/// anchored to each node's on-screen box via <c>getBoundingClientRect()</c>. Because they live in
/// screen space rather than inside the SVG, they are re-anchored on every <c>svg-pan-zoom</c>
/// pan/zoom (wired through the pan-zoom instance's <c>onPan</c>/<c>onZoom</c> callbacks) and on
/// window resize. A <c>running</c> node shows an animated CSS-<c>@keyframes</c> spinner (no
/// external image); every other (settled) status shows a static glyph. The auto-reload tag is
/// INDEPENDENT of the overlay (mirrors <c>LogSiteRenderer.IndexHtml(..., includeRefresh)</c>'s
/// during-run vs final duality) — present for the during-run diagram, dropped for the final
/// settled render.
/// </remarks>
private static string InjectStatusOverlay(
    string html, IReadOnlyDictionary<string, string> nodeStatuses, bool includeRefresh)
{
    // Same relaxed-encoder side-table treatment as taskFolderTargets: a JSON object (node id ->
    // status word) read back via textContent from a <script type="application/json"> element.
    string statusesJson = JsonSerializer.Serialize(nodeStatuses, new JsonSerializerOptions
    {
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    });

    // Auto-reload tag (during-run only) right after the viewport meta in <head>.
    if (includeRefresh)
    {
        html = html.Replace(
            "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",
            "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n"
                + "<meta http-equiv=\"refresh\" content=\"2\">",
            StringComparison.Ordinal);
    }

    // Status-badge CSS (spinner @keyframes + per-status colours) just before </style>.
    html = html.Replace(
        "</style>", StatusOverlayStyle + "\n</style>", StringComparison.Ordinal);

    // The node id -> status side-table, mirroring the task-folder-targets side-table, placed just
    // before the svg-pan-zoom script so it is already in the DOM when the module script reads it.
    html = html.Replace(
        "<script src=\"https://cdn.jsdelivr.net/npm/svg-pan-zoom",
        "<script type=\"application/json\" id=\"node-statuses\">" + statusesJson + "</script>\n"
            + "<script src=\"https://cdn.jsdelivr.net/npm/svg-pan-zoom",
        StringComparison.Ordinal);

    // The overlay functions, defined just before `let pz = null;` (module scope, after the graph/
    // targets consts, so they can read #node-statuses and be called from the try block below).
    html = html.Replace(
        "let pz = null;", StatusOverlayScript + "\n\nlet pz = null;", StringComparison.Ordinal);

    // Build the overlay on the SAME SVG mermaid.render just produced, right after the title-band
    // overlay (so it measures the SVG in its final, wrap-corrected shape).
    html = html.Replace(
        "  addTaskContainerOverlays(el);",
        "  addTaskContainerOverlays(el);\n  addStatusOverlays(el);",
        StringComparison.Ordinal);

    // Re-anchor the (screen-space) badges whenever the pan-zoom viewport pans or zooms.
    html = html.Replace(
        "minZoom: 0.1, maxZoom: 20, zoomScaleSensitivity: 0.3 });",
        "minZoom: 0.1, maxZoom: 20, zoomScaleSensitivity: 0.3,\n"
            + "                        onPan: positionStatusBadges, onZoom: positionStatusBadges });",
        StringComparison.Ordinal);

    // ...and on resize, plus one initial placement now that pan-zoom has fit the diagram.
    html = html.Replace(
        "  window.addEventListener('resize', () => { pz.resize(); pz.fit(); pz.center(); });",
        "  window.addEventListener('resize', () => { pz.resize(); pz.fit(); pz.center(); positionStatusBadges(); });\n"
            + "  positionStatusBadges();",
        StringComparison.Ordinal);

    return html;
}

// Live-run status-overlay CSS (issue #219), injected before </style> only on the non-null path.
// The spinner is a pure CSS @keyframes rotation (no external image), inherently distinct from a
// settled status's static glyph. `.status-<word>` colours mirror the log viewer's status palette.

